import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"即时解答与关键词扩展功能","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 始终生效的即时解答","slug":"_1-始终生效的即时解答","link":"#_1-始终生效的即时解答","children":[{"level":3,"title":"计算器与进制转换","slug":"计算器与进制转换","link":"#计算器与进制转换","children":[]},{"level":3,"title":"环境变量展开与查询","slug":"环境变量展开与查询","link":"#环境变量展开与查询","children":[]},{"level":3,"title":"快捷运行命令","slug":"快捷运行命令","link":"#快捷运行命令","children":[]},{"level":3,"title":"网址直达","slug":"网址直达","link":"#网址直达","children":[]},{"level":3,"title":"快速搜索窗口导入剪贴板文本","slug":"快速搜索窗口导入剪贴板文本","link":"#快速搜索窗口导入剪贴板文本","children":[]}]},{"level":2,"title":"2. 关键词触发功能（内置插件）","slug":"_2-关键词触发功能-内置插件","link":"#_2-关键词触发功能-内置插件","children":[]},{"level":2,"title":"3. 网页搜索快捷引擎","slug":"_3-网页搜索快捷引擎","link":"#_3-网页搜索快捷引擎","children":[]},{"level":2,"title":"4. 即时翻译","slug":"_4-即时翻译","link":"#_4-即时翻译","children":[]},{"level":2,"title":"5. 文件过滤器","slug":"_5-文件过滤器","link":"#_5-文件过滤器","children":[]},{"level":2,"title":"6. 自定义命令","slug":"_6-自定义命令","link":"#_6-自定义命令","children":[]}],"relativePath":"zh-CN/user-guide/instant-answers.md","filePath":"zh-CN/user-guide/instant-answers.md","lastUpdated":1791259880000}`),a={name:`zh-CN/user-guide/instant-answers.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="即时解答与关键词扩展功能" tabindex="-1">即时解答与关键词扩展功能 <a class="header-anchor" href="#即时解答与关键词扩展功能" aria-label="Permalink to “即时解答与关键词扩展功能”">​</a></h1><p>除了本地文件检索之外，Lertaro 还内置了一系列即时计算、系统工具与关键词扩展插件。无需等待文件检索，输入对应指令即可即刻得到答案或触发对应功能。</p><h2 id="_1-始终生效的即时解答" tabindex="-1">1. 始终生效的即时解答 <a class="header-anchor" href="#_1-始终生效的即时解答" aria-label="Permalink to “1. 始终生效的即时解答”">​</a></h2><p>无需输入任何前缀关键词，只要输入的文本匹配特定模式即可立即触发：</p><h3 id="计算器与进制转换" tabindex="-1">计算器与进制转换 <a class="header-anchor" href="#计算器与进制转换" aria-label="Permalink to “计算器与进制转换”">​</a></h3><p>直接在搜索框中输入数学表达式，计算结果将在第一行实时呈现。按下 <code>Enter</code> 键即可将计算结果复制到剪贴板：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>12 * (4 + 3)</span></span>
<span class="line"><span>100 * (1 - 0.15)</span></span></code></pre></div><p>支持常见的进制转换表达：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>255 to hex</span></span>
<span class="line"><span>0xFF to dec</span></span>
<span class="line"><span>101010 to bin</span></span></code></pre></div><h3 id="环境变量展开与查询" tabindex="-1">环境变量展开与查询 <a class="header-anchor" href="#环境变量展开与查询" aria-label="Permalink to “环境变量展开与查询”">​</a></h3><ul><li><strong>精准展开变量</strong>：输入 <code>%NAME%</code>（如 <code>%PATH%</code>、<code>%APPDATA%</code>）可直接查看变量值。对于包含多个路径的变量（如 <code>PATH</code>），Lertaro 会自动将其拆分为清晰的逐行列表，便于检查环境配置。</li><li><strong>模糊搜索变量</strong>：输入 <code>%</code> 加上关键词（如 <code>%temp</code>）可模糊搜索所有名称中包含该关键词的系统与用户环境变量。</li></ul><h3 id="快捷运行命令" tabindex="-1">快捷运行命令 <a class="header-anchor" href="#快捷运行命令" aria-label="Permalink to “快捷运行命令”">​</a></h3><p>无需先打开终端窗口，直接在搜索框中输入：</p><ul><li><code>#&lt;命令&gt;</code>：打开命令行窗口并<strong>以管理员权限</strong>执行该命令（例如 <code>#sfc /scannow</code> 或 <code>#net start LertaroService</code>）。</li><li><code>$&lt;命令&gt;</code>：打开命令行窗口以<strong>当前普通用户权限</strong>执行该命令（例如 <code>$ping 1.1.1.1</code> 或 <code>$ipconfig /all</code>）。</li></ul><p>在<strong>设置 → 插件 → 核心扩展 → 配置 → 系统命令执行器</strong>中，可选择 CMD（默认）、Windows PowerShell 或 PowerShell（pwsh）。启用<strong>在当前目录中执行</strong>后，内联搜索使用所在目录，快速搜索使用最近浏览的目录。未获取到目录时（例如首次使用快速搜索），使用用户主目录；选定目录不可用时停止执行。</p><p>勾选<strong>在级联文件夹浏览器中显示</strong>后，可通过<strong>在此目录执行命令</strong>输入命令、临时选择解释器及管理员权限。它始终使用菜单来源目录，子文件夹的右键菜单则使用该子文件夹。命令留空会打开所选解释器；<code>#</code>／<code>$</code> 前缀覆盖权限复选框。前缀后的内容精确为 <code>cmd</code>、<code>powershell</code> 或 <code>pwsh</code> 时（忽略大小写和首尾空格），直接打开对应程序；找不到该程序才回退到 CMD 执行原输入。普通命令所选的解释器缺失时会报错，不会换用另一种脚本语法。</p><p>CMD 会在切换目录前展开启动命令中的 <code>%CD%</code>。若提权或 UNC 路径导致系统改变初始目录，该变量可能仍指向旧目录；需要在启动命令中读取目录时，可选择 PowerShell 并使用 <code>$PWD</code>。</p><h3 id="网址直达" tabindex="-1">网址直达 <a class="header-anchor" href="#网址直达" aria-label="Permalink to “网址直达”">​</a></h3><p>直接输入或粘贴以 <code>http://</code> 或 <code>https://</code> 开头的完整网址，按下 <code>Enter</code> 即可立即在默认浏览器中打开该页面。输入合法的无协议网址（例如 <code>example.com</code>）时，快速搜索窗口会直接生成两条即时结果：<code>https://...</code> 和 <code>http://...</code>。无协议识别只针对一份硬编码的常见顶级域名白名单（一百多个后缀，如 <code>.com</code>、<code>.cn</code>、<code>.io</code>，并支持 <code>xn--</code> 国际化域名），不可设置；常见文件扩展名被刻意排除在外，其余输入仍按文件名检索，例如 <code>abc.txt</code> 不会生成网址结果，确需打开其他后缀的网址时请连同协议一起输入。每条结果都采用两行式的浏览器打开文案，搜索框内容不会被修改；已经包含协议的网址则只生成一条结果。</p><h3 id="快速搜索窗口导入剪贴板文本" tabindex="-1">快速搜索窗口导入剪贴板文本 <a class="header-anchor" href="#快速搜索窗口导入剪贴板文本" aria-label="Permalink to “快速搜索窗口导入剪贴板文本”">​</a></h3><p>在<strong>设置 → 通用 → 快速搜索窗口 → 自动将剪贴板文本填入快速搜索框</strong>（默认关闭）开启后，快速搜索窗口在没有预填内容的情况下被呼出时，如果剪贴板文本不为空且不同于该窗口上一次导入的剪贴板内容，就会自动填入并全选文本。相同内容不会重复导入，从 URI 或完整搜索窗口返回时的预填内容也不会被覆盖。</p><h2 id="_2-关键词触发功能-内置插件" tabindex="-1">2. 关键词触发功能（内置插件） <a class="header-anchor" href="#_2-关键词触发功能-内置插件" aria-label="Permalink to “2. 关键词触发功能（内置插件）”">​</a></h2><p>通过输入简短的<strong>触发关键词 + 空格</strong>，再输入实际查询内容，即可调用专项插件能力。各关键词均可在<a href="./settings/plugins.html"><strong>设置 → 插件</strong></a>中自定义修改。</p><p>分隔符可以是半角空格、全角空格或制表符；触发关键词本身不参与文件名匹配，也不会被高亮。当两个功能使用同一个关键词时，插件配置页会在该字段下方以黄色提示占用它的是谁，但不会阻止保存。</p><table tabindex="0"><thead><tr><th style="text-align:left;">默认关键词</th><th style="text-align:left;">插件名称</th><th style="text-align:left;">功能说明与使用场景</th><th style="text-align:left;">典型使用示例</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ps</code></td><td style="text-align:left;"><strong>进程管理</strong></td><td style="text-align:left;">按进程名、PID 或窗口标题搜索运行中的进程（支持拼音），回车一键结束进程。</td><td style="text-align:left;"><code>ps chrome</code> 或 <code>ps 1234</code></td></tr><tr><td style="text-align:left;"><code>win</code></td><td style="text-align:left;"><strong>窗口切换器</strong></td><td style="text-align:left;">搜索并即时切换到当前打开的应用窗口，支持后台实时抓取窗口缩略图。</td><td style="text-align:left;"><code>win code</code> 或 <code>win 微信</code></td></tr><tr><td style="text-align:left;"><code>bb</code></td><td style="text-align:left;"><strong>浏览器书签</strong></td><td style="text-align:left;">搜索 Chrome、Edge、Firefox 等浏览器的书签。</td><td style="text-align:left;"><code>bb github</code></td></tr><tr><td style="text-align:left;"><code>bh</code></td><td style="text-align:left;"><strong>浏览器历史</strong></td><td style="text-align:left;">搜索 Chrome、Edge、Firefox 等浏览器的历史访问记录。</td><td style="text-align:left;"><code>bh github</code></td></tr><tr><td style="text-align:left;"><code>set</code></td><td style="text-align:left;"><strong>设置搜索</strong></td><td style="text-align:left;">模糊搜索 Lertaro 自身的所有设置选项，选中即可直接跳转到对应设置页并高亮该项。</td><td style="text-align:left;"><code>set 快捷键</code> 或 <code>set 模糊</code></td></tr><tr><td style="text-align:left;"><code>flow</code></td><td style="text-align:left;"><strong>Flow 插件桥接</strong></td><td style="text-align:left;">列出所有已加载的 Flow.Launcher 插件及其触发词，支持调用 Flow 社区生态。</td><td style="text-align:left;"><code>flow</code></td></tr><tr><td style="text-align:left;"><code>cs</code></td><td style="text-align:left;"><strong>内容搜索</strong></td><td style="text-align:left;">搜索已建立索引的本地文档正文，并返回带片段的匹配文件。</td><td style="text-align:left;"><code>cs 项目计划</code></td></tr></tbody></table><p>选中 <code>win</code> 搜索结果后，打开动作菜单（<code>Ctrl+O</code>）即可使用以下窗口操作。两项均以窗口所在显示器的可用区域为准（避开任务栏），最小化或最大化的窗口会先还原再定位。</p><ul><li>适配屏幕并居中（<code>s</code>）：分别检查窗口的宽和高，仅将超过可用区域的维度缩小至对应可用尺寸减 12 像素，然后居中。未超出的维度（包括恰好相等）保持不变。</li><li>位置居中（<code>e</code>）：将还原后的窗口移到可用区域正中央，不调整大小。</li></ul><h2 id="_3-网页搜索快捷引擎" tabindex="-1">3. 网页搜索快捷引擎 <a class="header-anchor" href="#_3-网页搜索快捷引擎" aria-label="Permalink to “3. 网页搜索快捷引擎”">​</a></h2><p>网页搜索插件内置了主流搜索引擎快捷方式，输入对应前缀并跟随关键词即可一键拉起浏览器搜索：</p><table tabindex="0"><thead><tr><th style="text-align:left;">快捷词</th><th style="text-align:left;">对应搜索引擎</th><th style="text-align:left;">示例</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>bd</code></td><td style="text-align:left;">百度 (Baidu)</td><td style="text-align:left;"><code>bd 深度学习</code></td><td style="text-align:left;">在百度中搜索关键词</td></tr><tr><td style="text-align:left;"><code>g</code></td><td style="text-align:left;">谷歌 (Google)</td><td style="text-align:left;"><code>g lertaro github</code></td><td style="text-align:left;">在 Google 中搜索关键词</td></tr><tr><td style="text-align:left;"><code>bing</code></td><td style="text-align:left;">必应 (Bing)</td><td style="text-align:left;"><code>bing 微软文档</code></td><td style="text-align:left;">在 Bing 中搜索关键词</td></tr><tr><td style="text-align:left;"><code>gh</code></td><td style="text-align:left;">GitHub</td><td style="text-align:left;"><code>gh Lertaro</code></td><td style="text-align:left;">直接在 GitHub 仓库中搜索</td></tr><tr><td style="text-align:left;"><code>wiki</code></td><td style="text-align:left;">维基百科 (Wikipedia)</td><td style="text-align:left;"><code>wiki 量子力学</code></td><td style="text-align:left;">在维基百科中查阅词条</td></tr><tr><td style="text-align:left;"><code>yt</code></td><td style="text-align:left;">YouTube</td><td style="text-align:left;"><code>yt lofi hip hop</code></td><td style="text-align:left;">在 YouTube 中搜索视频</td></tr></tbody></table><p>你可以在<strong>设置 → 插件 → 网页搜索 → 配置</strong>中自由新增、修改或删除搜索引擎与自定义 URL 模板。</p><h2 id="_4-即时翻译" tabindex="-1">4. 即时翻译 <a class="header-anchor" href="#_4-即时翻译" aria-label="Permalink to “4. 即时翻译”">​</a></h2><p>输入默认触发词 <code>tr</code> 并在其后输入待翻译的内容，即可自动翻译为 Lertaro 当前所选的界面语言：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tr Hello, how are you today?</span></span></code></pre></div><ul><li>翻译结果随输入异步呈现，按 <code>Enter</code> 键即可一键复制译文。</li><li>可在<strong>设置 → 插件 → 翻译 → 配置</strong>中更改触发词或查看联网状态。</li></ul><h2 id="_5-文件过滤器" tabindex="-1">5. 文件过滤器 <a class="header-anchor" href="#_5-文件过滤器" aria-label="Permalink to “5. 文件过滤器”">​</a></h2><p>在<strong>设置 → 插件 → 文件过滤器 → 配置</strong>中，你可以为触发关键字绑定特定目录，让普通搜索可以限定在这些目录内：</p><ul><li><strong>范围文件夹列表</strong>：一行一个路径（如 <code>D:\\Engineering\\Drawings</code>），也支持环境变量（如 <code>%TEMP%</code>）与系统虚拟路径（如 <code>shell:Downloads</code>），无法解析为真实文件夹的条目会被跳过。搜索结果来自文件索引，因此文件夹需被索引覆盖（已启用索引的本地盘，或在<strong>设置 → 索引 → 文件夹</strong>中添加，支持网络共享路径）；未被索引覆盖的文件夹会被跳过并记录警告日志。</li><li><strong>匹配规则</strong>：文件名通配模式（如 <code>*.dwg;*.dxf</code>，文件夹始终保留）。</li><li><strong>触发关键字</strong>：绑定前缀（如 <code>cad</code>）后，在快捷搜索框输入 <code>cad 零件图</code> 即可只在绑定的文件夹内执行常规索引检索（按文件名模糊匹配，含拼音别名）；仅输入关键字时会提示继续输入。</li></ul><h2 id="_6-自定义命令" tabindex="-1">6. 自定义命令 <a class="header-anchor" href="#_6-自定义命令" aria-label="Permalink to “6. 自定义命令”">​</a></h2><p>在<strong>设置 → 插件 → 自定义命令 → 配置</strong>中，你可以将任意复杂的命令行工具、脚本或外部应用包装为一个简短的启动命令：</p><ul><li><strong>参数占位符</strong>：支持位置占位符 <code>%s1</code>、<code>%s2</code>……（对应以空格分隔的参数）以及全文占位符 <code>%s</code>（代表关键词后的所有输入文本）。</li><li><strong>在当前目录中执行</strong>：覆盖固定工作目录；级联菜单使用来源目录，内联搜索使用所在目录，快速搜索使用最近浏览的目录。目录不可用时停止执行。默认关闭，保留原有配置行为。</li><li><strong>快速导航集成</strong>：勾选“在快速导航中显示”后，该命令会直接作为菜单项出现在<a href="./hotkeys.html#_3-快速导航-鼠标触发"><strong>快速导航</strong></a>中，支持使用 <code>/</code> 创建多级子菜单分类（如 <code>开发工具/重启服务</code>）。</li></ul>`,41)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};